SELECT p.gender, CAST(p.anchor_age AS INT) AS age, s.sepsis, s.septic_shock, i.intime, i.outtime, i.los, COUNT(DISTINCT a.subject_id) AS N, CAST(COUNT(DISTINCT CASE WHEN a.deathtime IS NOT NULL THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS mortality_rate, CAST(COUNT(DISTINCT CASE WHEN d.ckd_stage IS NOT NULL THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS ckd_prevalence, CAST(COUNT(DISTINCT CASE WHEN d.diabetes_med_icd_9_cm IS NOT NULL THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS diabetes_prevalence FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id JOIN diagnoses_icd s ON a.subject_id = s.subject_id AND a.hadm_id = s.hadm_id JOIN d_items d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.gender = 'F' AND CAST(p.anchor_age AS INT) BETWEEN 49 AND 59 AND s.sepsis = 'Y' AND s.septic_shock = 'N' AND i.intime <= '2020-01-01' AND (i.outtime - i.intime) <= 1 AND (i.outtime - i.intime) >= 0 AND i.los <= 5 GROUP BY p.gender, age, s.sepsis, s.septic_shock, i.intime, i.outtime, i.los ORDER BY p.gender, age, s.sepsis, s.septic_shock, i.intime, i.outtime, i.los NULLS LAST;